// n8n 2.x no expone $helpers ni fetch en el nodo Code: el cliente HTTP es this.helpers.
const helpers = this.helpers;
const BASE = $env.FASTAPI_BASE_URL;
const chatbotKey  = $env.CHATBOT_INTERNAL_KEY;
const geminiKey   = $env.GEMINI_API_KEY;
const supabaseUrl = $env.SUPABASE_URL;
const supabaseKey = $env.SUPABASE_SERVICE_ROLE_KEY;

async function get(path) {
  return await helpers.httpRequest({
    method: 'GET',
    url: BASE + path,
    headers: { 'X-Chatbot-Key': chatbotKey },
    json: true,
  });
}

const [faqResp, cursosResp, avisosResp] = await Promise.all([
  get('/chatbot/faq'),
  get('/chatbot/cursos/info'),
  get('/chatbot/avisos'),
]);

const docs = [];

for (const item of (faqResp.data && faqResp.data.faq) || []) {
  docs.push({
    source: 'faq',
    external_id: item.q,
    content: `Pregunta: ${item.q}\nRespuesta: ${item.a}`,
  });
}

for (const c of (cursosResp.data && cursosResp.data.cursos) || []) {
  docs.push({
    source: 'curso',
    external_id: String(c.id),
    content: `Curso: ${c.nombre}. ${c.descripcion || ''} Modalidad: ${c.modalidad}. Categoria: ${c.categoria}. Cuota mensual: $${c.monto_cuota}.`,
  });
}

for (const a of (avisosResp.data && avisosResp.data.avisos) || []) {
  docs.push({
    source: 'aviso',
    external_id: String(a.id),
    content: `Aviso (${a.fecha_publicacion}): ${a.titulo}. ${a.contenido}`,
  });
}

let upserted = 0;
const errors = [];

for (const doc of docs) {
  try {
    const embedResp = await helpers.httpRequest({
      method: 'POST',
      url: `https://generativelanguage.googleapis.com/v1beta/models/gemini-embedding-001:embedContent?key=${geminiKey}`,
      headers: { 'Content-Type': 'application/json' },
      body: {
        model: 'models/gemini-embedding-001', outputDimensionality: 768,
        content: { parts: [{ text: doc.content }] },
      },
      json: true,
    });
    const embedding = embedResp.embedding.values;

    await helpers.httpRequest({
      method: 'POST',
      url: `${supabaseUrl}/rest/v1/documents?on_conflict=source,external_id`,
      headers: {
        apikey: supabaseKey,
        Authorization: `Bearer ${supabaseKey}`,
        'Content-Type': 'application/json',
        Prefer: 'resolution=merge-duplicates',
      },
      body: {
        source: doc.source,
        external_id: doc.external_id,
        content: doc.content,
        embedding,
        updated_at: new Date().toISOString(),
      },
      json: true,
    });
    upserted++;
  } catch (e) {
    errors.push({ doc: doc.external_id, error: e.message });
  }
}

return [{ json: { upserted, total: docs.length, errors } }];
